      {"country": "Brazil", "per_capita_m3": 27436},
      {"country": "Canada", "per_capita_m3": 80620}
    ]
  },
  "groundwater_extraction": {
    "data": [
      {"country": "India", "extraction_recharge_ratio": 0.58},
      {"country": "Pakistan", "extraction_recharge_ratio": 1.16},
      {"country": "Egypt", "extraction_recharge_ratio": 1.63},
      {"country": "Saudi Arabia", "extraction_recharge_ratio": 5.66},
      {"country": "Mexico", "extraction_recharge_ratio": 0.75},
      {"country": "South Africa", "extraction_recharge_ratio": 0.98},
      {"country": "Australia", "extraction_recharge_ratio": 0.23},
