      {"country": "Brazil", "extraction_recharge_ratio": 0.1},
      {"country": "Canada", "extraction_recharge_ratio": 0.05}
    ]
  },
  "precipitation_trends": {
    "data": [
      {"country": "India", "decade": "1990s", "mean_precip_mm": 1120},
      {"country": "India", "decade": "2000s", "mean_precip_mm": 1095},
