}

countries = ["Saudi Arabia", "Egypt", "Pakistan", "India", "South Africa", "Mexico", "Australia", "United States", "Brazil", "Canada"]
# Ordered roughly by stress level

merged = {}
for c in countries:
    merged[c] = {}

for item in data["water_supply_demand"]["data"]:
    if item["country"] in merged:
        merged[item["country"]]["supply_demand"] = item["supply_demand_ratio"]

for item in data["per_capita_freshwater"]["data"]:
    if item["country"] in merged:
        merged[item["country"]]["per_capita"] = item["per_capita_m3"]

for item in data["groundwater_extraction"]["data"]:
    if item["country"] in merged:
        merged[item["country"]]["gw_ratio"] = item["extraction_recharge_ratio"]

for item in data["precipitation_trends"]["data"]:
    c = item["country"]
    d = item["decade"]
    if c in merged:
        merged[c][f"precip_{d}"] = item["mean_precip_mm"]

for c, v in merged.items():
    v["precip_trend"] = "increasing" if v["precip_2010s"] > v["precip_1990s"] else "decreasing"
    v["precip_change_pct"] = (v["precip_2010s"] - v["precip_1990s"]) / v["precip_1990s"] * 100

html = f"""<!DOCTYPE html>
<html lang="en" class="theme-light">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>Global Water Crisis Hotspots</title>
    <link href="file:///app/libs/fonts/inter.css" rel="stylesheet">
    <script src="file:///app/libs/chart.js"></script>
    <style>
        :root {{
            --bg: #ffffff;
            --surface: #f8fafc;
            --border: #e2e8f0;
            --text: #0f172a;
            --text-secondary: #64748b;
            --accent: #0284c7;
            --negative: #dc2626;
            --positive: #16a34a;
            --warning: #ea580c;
        }}
        .theme-dark {{
            --bg: #030712;
            --surface: #111827;
            --border: #374151;
            --text: #f9fafb;
            --text-secondary: #9ca3af;
            --accent: #38bdf8;
            --negative: #f87171;
            --positive: #4ade80;
            --warning: #fb923c;
        }}
        body {{
            margin: 0;
            font-family: 'Inter', sans-serif;
            background-color: var(--bg);
            color: var(--text);
            /* Slide size 1920x1080 */
            width: 1920px;
            height: 1080px;
            overflow: hidden;
            display: flex;
            flex-direction: column;
            box-sizing: border-box;
        }}
        .header {{
            padding: 40px 60px 20px;
            border-bottom: 1px solid var(--border);
        }}
        h1 {{
            margin: 0 0 10px 0;
            font-size: 3.5rem;
            font-weight: 700;
            letter-spacing: -0.03em;
        }}
        .subtitle {{
            margin: 0;
            font-size: 1.5rem;
            color: var(--text-secondary);
        }}
        .main-content {{
            flex: 1;
            display: grid;
            grid-template-columns: 1fr 1fr;
            grid-template-rows: 1fr 1fr;
            gap: 30px;
            padding: 40px 60px;
            box-sizing: border-box;
        }}
        .card {{
            background: var(--surface);
            border: 1px solid var(--border);
            border-radius: 16px;
            padding: 30px;
            display: flex;
            flex-direction: column;
        }}
        .card h2 {{
            margin: 0 0 20px 0;
            font-size: 1.8rem;
            font-weight: 600;
        }}
        .chart-wrapper {{
            flex: 1;
            position: relative;
            min-height: 250px;
        }}
        .full-width {{
            grid-column: 1 / -1;
        }}
    </style>
</head>
<body>
    <div class="header">
        <h1>Global Water Crisis Hotspots</h1>
        <p class="subtitle">Multi-indicator analysis of severe water stress convergence across 10 regions</p>
    </div>

    <div class="main-content">
        <div class="card">
            <h2>Supply-to-Demand & Groundwater Depletion</h2>
            <div class="chart-wrapper">
                <canvas id="scatterChart" role="img" aria-label="Scatter plot showing supply-demand ratio vs groundwater extraction"></canvas>
            </div>
        </div>

        <div class="card">
            <h2>Precipitation Trends (1990s-2010s)</h2>
            <div class="chart-wrapper">
                <canvas id="precipChart" role="img" aria-label="Line chart showing precipitation trends"></canvas>
            </div>
        </div>

        <div class="card full-width">
            <h2>Per Capita Freshwater Contrast (m³/person/year)</h2>
            <div class="chart-wrapper">
                <canvas id="barChart" role="img" aria-label="Bar chart showing per capita freshwater availability"></canvas>
            </div>
        </div>
    </div>

    <script>
        Chart.defaults.animation = false;
        Chart.defaults.font.family = 'Inter';
        Chart.defaults.color = '#64748b';

        const mergedData = {json.dumps(merged)};
        const countries = {json.dumps(countries)};

        // 1. Scatter Plot: Supply/Demand vs Groundwater Ratio
        const scatterCtx = document.getElementById('scatterChart').getContext('2d');
        new Chart(scatterCtx, {{
            type: 'scatter',
            data: {{
                datasets: [
                    {{
                        label: 'High Stress Countries',
                        data: countries.filter(c => mergedData[c].supply_demand < 1.0 || mergedData[c].gw_ratio > 1.0).map(c => ({{
                            x: mergedData[c].supply_demand,
                            y: mergedData[c].gw_ratio,
                            country: c
                        }})),
                        backgroundColor: '#dc2626',
                        pointRadius: 10,
                        pointHoverRadius: 12
                    }},
                    {{
                        label: 'Lower Stress Countries',
                        data: countries.filter(c => mergedData[c].supply_demand >= 1.0 && mergedData[c].gw_ratio <= 1.0).map(c => ({{
                            x: mergedData[c].supply_demand,
                            y: mergedData[c].gw_ratio,
                            country: c
                        }})),
                        backgroundColor: '#0284c7',
                        pointRadius: 10,
                        pointHoverRadius: 12
                    }}
                ]
            }},
            options: {{
                responsive: true,
                maintainAspectRatio: false,
                plugins: {{
                    tooltip: {{
                        callbacks: {{
                            label: (ctx) => ctx.raw.country + ': Supply/Demand=' + ctx.raw.x + ', GW Ratio=' + ctx.raw.y
                        }}
                    }},
                    legend: {{ position: 'bottom' }}
                }},
                scales: {{
                    x: {{
                        title: {{ display: true, text: 'Supply/Demand Ratio (<1 is deficit)', font: {{ size: 14, weight: 'bold' }} }},
                        grid: {{ color: '#e2e8f0' }}
                    }},
                    y: {{
                        title: {{ display: true, text: 'GW Extraction/Recharge (>1 is overdraft)', font: {{ size: 14, weight: 'bold' }} }},
                        grid: {{ color: '#e2e8f0' }}
                    }}
                }}
            }}
        }});

        // 2. Line Chart: Precipitation
        const precipCtx = document.getElementById('precipChart').getContext('2d');
        const precipDatasets = countries.map((c, i) => {{
            const isDecreasing = mergedData[c].precip_trend === 'decreasing';
            return {{
                label: c,
                data: [mergedData[c].precip_1990s, mergedData[c].precip_2000s, mergedData[c].precip_2010s],
                borderColor: isDecreasing ? '#dc2626' : '#16a34a',
                borderWidth: isDecreasing ? 3 : 1.5,
                borderDash: isDecreasing ? [] : [5, 5],
                tension: 0.1,
                pointRadius: 4
            }};
        }});

        new Chart(precipCtx, {{
            type: 'line',
            data: {{
                labels: ['1990s', '2000s', '2010s'],
                datasets: precipDatasets
            }},
            options: {{
                responsive: true,
                maintainAspectRatio: false,
                plugins: {{
                    legend: {{ position: 'right', labels: {{ boxWidth: 12 }} }}
                }},
                scales: {{
                    y: {{ title: {{ display: true, text: 'Precipitation (mm/yr)' }}, grid: {{ color: '#e2e8f0' }} }}
                }}
            }}
        }});

        // 3. Bar Chart: Per Capita Freshwater (Log Scale)
        const barCtx = document.getElementById('barChart').getContext('2d');
        new Chart(barCtx, {{
            type: 'bar',
            data: {{
                labels: countries,
                datasets: [{{
                    label: 'Per Capita Freshwater (m³)',
                    data: countries.map(c => mergedData[c].per_capita),
                    backgroundColor: countries.map(c => mergedData[c].per_capita < 1000 ? '#dc2626' : (mergedData[c].per_capita < 5000 ? '#ea580c' : '#0284c7')),
                    borderRadius: 4
                }}]
            }},
            options: {{
                responsive: true,
                maintainAspectRatio: false,
                plugins: {{
                    legend: {{ display: false }}
                }},
                scales: {{
                    y: {{
                        type: 'logarithmic',
                        title: {{ display: true, text: 'm³/person/yr (Log Scale)' }},
                        grid: {{ color: '#e2e8f0' }}
                    }},
                    x: {{ grid: {{ display: false }} }}
                }}
            }}
        }});
    </script>
</body>
</html>"""

with open('/app/tmp_viz.html', 'w', encoding='utf-8') as f:
    f.write(html)

